arguments.command:
cat > /tmp/askpass-monica.sh <<'EOF'
#!/bin/sh
case "$1" in
  Username*) echo "x-access-token" ;;
  Password*) echo "$GITHUB_TOKEN" ;;
esac
EOF
chmod 700 /tmp/askpass-monica.sh; echo ok; cd "$GITHUB_WORKSPACE"; for b in rachel monica phoebe joey chandler ross; do echo "=== $b ==="; git log --format='%H %cI %s' -2 origin/friend/$b; done
